
import { useState } from 'react';
import { categories, brands, conditionOptions } from '../../../mocks/usedPartsList';

interface FilterSidebarProps {
  selectedCategory: string;
  selectedBrand: string;
  selectedCondition: string;
  priceMin: string;
  priceMax: string;
  onCategoryChange: (v: string) => void;
  onBrandChange: (v: string) => void;
  onConditionChange: (v: string) => void;
  onPriceMinChange: (v: string) => void;
  onPriceMaxChange: (v: string) => void;
  onReset: () => void;
}

export default function FilterSidebar({
  selectedCategory,
  selectedBrand,
  selectedCondition,
  priceMin,
  priceMax,
  onCategoryChange,
  onBrandChange,
  onConditionChange,
  onPriceMinChange,
  onPriceMaxChange,
  onReset,
}: FilterSidebarProps) {
  const [brandExpanded, setBrandExpanded] = useState(false);
  const visibleBrands = brandExpanded ? brands : brands.slice(0, 8);

  return (
    <div className="w-60 flex-shrink-0">
      <div className="bg-white border border-gray-200 rounded-lg overflow-hidden sticky top-4">
        <div className="bg-green-700 text-white py-3 px-4 flex items-center justify-between">
          <span className="font-bold text-sm flex items-center gap-2">
            <i className="ri-filter-3-line"></i>
            絞り込み検索
          </span>
          <button
            onClick={onReset}
            className="text-xs underline hover:text-green-200 cursor-pointer whitespace-nowrap"
          >
            クリア
          </button>
        </div>

        <div className="p-4 space-y-5">
          {/* カテゴリ */}
          <div>
            <h4 className="text-sm font-bold text-gray-800 mb-2 flex items-center gap-1">
              <i className="ri-folder-line text-green-600 w-4 h-4 flex items-center justify-center"></i>
              カテゴリ
            </h4>
            <div className="space-y-1">
              {categories.map((cat) => (
                <button
                  key={cat}
                  onClick={() => onCategoryChange(cat)}
                  className={`block w-full text-left text-sm py-1.5 px-3 rounded cursor-pointer transition-colors whitespace-nowrap ${
                    selectedCategory === cat
                      ? 'bg-green-100 text-green-800 font-bold'
                      : 'text-gray-600 hover:bg-gray-100'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>
          </div>

          {/* ブランド */}
          <div>
            <h4 className="text-sm font-bold text-gray-800 mb-2 flex items-center gap-1">
              <i className="ri-price-tag-line text-green-600 w-4 h-4 flex items-center justify-center"></i>
              ブランド
            </h4>
            <div className="space-y-1">
              {visibleBrands.map((br) => (
                <button
                  key={br}
                  onClick={() => onBrandChange(br)}
                  className={`block w-full text-left text-sm py-1.5 px-3 rounded cursor-pointer transition-colors whitespace-nowrap ${
                    selectedBrand === br
                      ? 'bg-green-100 text-green-800 font-bold'
                      : 'text-gray-600 hover:bg-gray-100'
                  }`}
                >
                  {br}
                </button>
              ))}
              {brands.length > 8 && (
                <button
                  onClick={() => setBrandExpanded(!brandExpanded)}
                  className="text-xs text-green-600 hover:underline cursor-pointer px-3 pt-1 whitespace-nowrap"
                >
                  {brandExpanded ? '閉じる' : `他${brands.length - 8}件を表示`}
                </button>
              )}
            </div>
          </div>

          {/* 商品状態 */}
          <div>
            <h4 className="text-sm font-bold text-gray-800 mb-2 flex items-center gap-1">
              <i className="ri-shield-check-line text-green-600 w-4 h-4 flex items-center justify-center"></i>
              商品状態
            </h4>
            <div className="space-y-1">
              {conditionOptions.map((cond) => (
                <button
                  key={cond}
                  onClick={() => onConditionChange(cond)}
                  className={`block w-full text-left text-sm py-1.5 px-3 rounded cursor-pointer transition-colors whitespace-nowrap ${
                    selectedCondition === cond
                      ? 'bg-green-100 text-green-800 font-bold'
                      : 'text-gray-600 hover:bg-gray-100'
                  }`}
                >
                  {cond}
                </button>
              ))}
            </div>
          </div>

          {/* 価格帯 */}
          <div>
            <h4 className="text-sm font-bold text-gray-800 mb-2 flex items-center gap-1">
              <i className="ri-money-yen-circle-line text-green-600 w-4 h-4 flex items-center justify-center"></i>
              価格帯
            </h4>
            <div className="flex items-center gap-2">
              <input
                type="number"
                placeholder="下限"
                value={priceMin}
                onChange={(e) => onPriceMinChange(e.target.value)}
                className="w-full border border-gray-300 rounded px-2 py-1.5 text-sm focus:outline-none focus:border-green-500 cursor-text"
              />
              <span className="text-gray-400 text-xs">〜</span>
              <input
                type="number"
                placeholder="上限"
                value={priceMax}
                onChange={(e) => onPriceMaxChange(e.target.value)}
                className="w-full border border-gray-300 rounded px-2 py-1.5 text-sm focus:outline-none focus:border-green-500 cursor-text"
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
