import { useState, useMemo } from 'react';
import { Link } from 'react-router-dom';
import { usedPartsListData, sortOptions } from '../../mocks/usedPartsList';
import FilterSidebar from './components/FilterSidebar';
import UsedPartCard from './components/UsedPartCard';
import GlobalHeader from '../../components/feature/GlobalHeader';
import GlobalFooter from '../../components/feature/GlobalFooter';
import Breadcrumb from '../../components/feature/Breadcrumb';

export default function UsedPartsList() {
  const [selectedCategory, setSelectedCategory] = useState('すべて');
  const [selectedBrand, setSelectedBrand] = useState('すべて');
  const [selectedCondition, setSelectedCondition] = useState('すべて');
  const [priceMin, setPriceMin] = useState('');
  const [priceMax, setPriceMax] = useState('');
  const [sortBy, setSortBy] = useState('newest');
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 9;

  const filteredParts = useMemo(() => {
    let result = [...usedPartsListData];

    if (selectedCategory !== 'すべて') {
      result = result.filter((p) => p.category === selectedCategory);
    }
    if (selectedBrand !== 'すべて') {
      result = result.filter((p) => p.brand === selectedBrand);
    }
    if (selectedCondition !== 'すべて') {
      result = result.filter((p) => p.condition === selectedCondition);
    }
    if (priceMin) {
      result = result.filter((p) => p.price >= Number(priceMin));
    }
    if (priceMax) {
      result = result.filter((p) => p.price <= Number(priceMax));
    }

    switch (sortBy) {
      case 'price-asc':
        result.sort((a, b) => a.price - b.price);
        break;
      case 'price-desc':
        result.sort((a, b) => b.price - a.price);
        break;
      case 'popular':
        result.sort((a, b) => {
          const aPopular = a.tags.includes('人気') ? 1 : 0;
          const bPopular = b.tags.includes('人気') ? 1 : 0;
          return bPopular - aPopular;
        });
        break;
      default:
        break;
    }

    return result;
  }, [
    selectedCategory,
    selectedBrand,
    selectedCondition,
    priceMin,
    priceMax,
    sortBy,
  ]);

  const totalPages = Math.ceil(filteredParts.length / itemsPerPage);
  const paginatedParts = filteredParts.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage,
  );

  const handleReset = () => {
    setSelectedCategory('すべて');
    setSelectedBrand('すべて');
    setSelectedCondition('すべて');
    setPriceMin('');
    setPriceMax('');
    setCurrentPage(1);
  };

  const handleFilterChange =
    (setter: (v: string) => void) => (value: string) => {
      setter(value);
      setCurrentPage(1);
    };

  return (
    <div className="min-h-screen bg-white">
      {/* 共通ヘッダー */}
      <GlobalHeader />

      {/* ページヘッダーバナー */}
      <div className="bg-gradient-to-r from-green-700 to-emerald-600 py-6 px-6">
        <div className="max-w-[1400px] mx-auto flex items-center justify-between">
          <div>
            <h1 className="text-white text-2xl font-bold flex items-center gap-3">
              <i className="ri-recycle-line text-3xl"></i>
              中古パーツ一覧
            </h1>
            <p className="text-green-100 text-sm mt-1">
              掘り出し物が見つかる！厳選中古パーツを多数取り揃え
            </p>
          </div>
          <div className="flex items-center gap-3">
            <div className="bg-white/20 rounded-lg px-4 py-2 text-white text-center">
              <p className="text-2xl font-bold">{usedPartsListData.length}</p>
              <p className="text-xs">商品掲載中</p>
            </div>
          </div>
        </div>
      </div>

      {/* パンくずリスト */}
      <Breadcrumb items={[{ label: '中古パーツ一覧' }]} />

      {/* メインコンテンツ */}
      <main className="max-w-[1400px] mx-auto px-6 pb-12">
        <div className="flex gap-6">
          {/* サイドバー */}
          <FilterSidebar
            selectedCategory={selectedCategory}
            selectedBrand={selectedBrand}
            selectedCondition={selectedCondition}
            priceMin={priceMin}
            priceMax={priceMax}
            onCategoryChange={handleFilterChange(setSelectedCategory)}
            onBrandChange={handleFilterChange(setSelectedBrand)}
            onConditionChange={handleFilterChange(setSelectedCondition)}
            onPriceMinChange={(v) => {
              setPriceMin(v);
              setCurrentPage(1);
            }}
            onPriceMaxChange={(v) => {
              setPriceMax(v);
              setCurrentPage(1);
            }}
            onReset={handleReset}
          />

          {/* 商品一覧 */}
          <div className="flex-1">
            {/* ソートバー */}
            <div className="flex items-center justify-between mb-4 bg-gray-50 border border-gray-200 rounded-lg px-4 py-3">
              <div className="flex items-center gap-3">
                <p className="text-sm text-gray-700">
                  <strong className="text-green-700">{filteredParts.length}</strong>{' '}
                  件の商品
                </p>
                {(selectedCategory !== 'すべて' ||
                  selectedBrand !== 'すべて' ||
                  selectedCondition !== 'すべて' ||
                  priceMin ||
                  priceMax) && (
                  <div className="flex items-center gap-2 flex-wrap">
                    {selectedCategory !== 'すべて' && (
                      <span className="bg-green-100 text-green-800 text-xs px-2 py-1 rounded flex items-center gap-1 whitespace-nowrap">
                        {selectedCategory}
                        <button
                          onClick={() => {
                            setSelectedCategory('すべて');
                            setCurrentPage(1);
                          }}
                          className="hover:text-red-600 cursor-pointer"
                        >
                          <i className="ri-close-line"></i>
                        </button>
                      </span>
                    )}
                    {selectedBrand !== 'すべて' && (
                      <span className="bg-green-100 text-green-800 text-xs px-2 py-1 rounded flex items-center gap-1 whitespace-nowrap">
                        {selectedBrand}
                        <button
                          onClick={() => {
                            setSelectedBrand('すべて');
                            setCurrentPage(1);
                          }}
                          className="hover:text-red-600 cursor-pointer"
                        >
                          <i className="ri-close-line"></i>
                        </button>
                      </span>
                    )}
                    {selectedCondition !== 'すべて' && (
                      <span className="bg-green-100 text-green-800 text-xs px-2 py-1 rounded flex items-center gap-1 whitespace-nowrap">
                        {selectedCondition}
                        <button
                          onClick={() => {
                            setSelectedCondition('すべて');
                            setCurrentPage(1);
                          }}
                          className="hover:text-red-600 cursor-pointer"
                        >
                          <i className="ri-close-line"></i>
                        </button>
                      </span>
                    )}
                  </div>
                )}
              </div>
              <div className="flex items-center gap-2">
                <span className="text-xs text-gray-500 whitespace-nowrap">
                  並び替え：
                </span>
                <select
                  value={sortBy}
                  onChange={(e) => setSortBy(e.target.value)}
                  className="border border-gray-300 rounded px-3 py-1.5 text-sm cursor-pointer focus:outline-none focus:border-green-500"
                >
                  {sortOptions.map((opt) => (
                    <option key={opt.value} value={opt.value}>
                      {opt.label}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            {/* 商品グリッド */}
            {paginatedParts.length > 0 ? (
              <div className="grid grid-cols-3 gap-4 mb-8">
                {paginatedParts.map((part) => (
                  <UsedPartCard key={part.id} part={part} />
                ))}
              </div>
            ) : (
              <div className="text-center py-20 bg-gray-50 rounded-lg">
                <i className="ri-search-line text-5xl text-gray-300 mb-4"></i>
                <p className="text-gray-500 text-lg mb-2">
                  該当する商品が見つかりませんでした
                </p>
                <p className="text-gray-400 text-sm mb-4">
                  条件を変更して再度お試しください
                </p>
                <button
                  onClick={handleReset}
                  className="bg-green-600 text-white px-6 py-2 rounded-lg font-bold text-sm hover:bg-green-700 cursor-pointer whitespace-nowrap"
                >
                  条件をリセット
                </button>
              </div>
            )}

            {/* ページネーション */}
            {totalPages > 1 && (
              <div className="flex items-center justify-center gap-2">
                <button
                  onClick={() =>
                    setCurrentPage(Math.max(1, currentPage - 1))
                  }
                  disabled={currentPage === 1}
                  className={`w-9 h-9 rounded flex items-center justify-center text-sm whitespace-nowrap ${
                    currentPage === 1
                      ? 'bg-gray-100 text-gray-300 cursor-not-allowed'
                      : 'bg-white border border-gray-300 text-gray-700 hover:bg-gray-100 cursor-pointer'
                  }`}
                >
                  <i className="ri-arrow-left-s-line"></i>
                </button>
                {Array.from({ length: totalPages }, (_, i) => i + 1).map(
                  (page) => (
                    <button
                      key={page}
                      onClick={() => setCurrentPage(page)}
                      className={`w-9 h-9 rounded flex items-center justify-center text-sm cursor-pointer whitespace-nowrap ${
                        currentPage === page
                          ? 'bg-green-700 text-white font-bold'
                          : 'bg-white border border-gray-300 text-gray-700 hover:bg-gray-100'
                      }`}
                    >
                      {page}
                    </button>
                  ),
                )}
                <button
                  onClick={() =>
                    setCurrentPage(Math.min(totalPages, currentPage + 1))
                  }
                  disabled={currentPage === totalPages}
                  className={`w-9 h-9 rounded flex items-center justify-center text-sm whitespace-nowrap ${
                    currentPage === totalPages
                      ? 'bg-gray-100 text-gray-300 cursor-not-allowed'
                      : 'bg-white border border-gray-300 text-gray-700 hover:bg-gray-100 cursor-pointer'
                  }`}
                >
                  <i className="ri-arrow-right-s-line"></i>
                </button>
              </div>
            )}

            {/* 中古パーツ安心保証バナー */}
            <div className="mt-8 bg-gradient-to-r from-green-50 to-emerald-50 border border-green-200 rounded-lg p-6">
              <div className="flex items-start gap-4">
                <div className="w-12 h-12 bg-green-600 rounded-full flex items-center justify-center flex-shrink-0">
                  <i className="ri-shield-check-line text-white text-xl"></i>
                </div>
                <div>
                  <h3 className="text-base font-bold text-gray-800 mb-2">
                    AutoGarage 中古パーツ安心保証
                  </h3>
                  <div className="grid grid-cols-3 gap-4">
                    <div className="flex items-start gap-2">
                      <i className="ri-check-double-line text-green-600 w-4 h-4 flex items-center justify-center mt-0.5"></i>
                      <p className="text-xs text-gray-600">
                        商品到着後7日以内の初期不良対応
                      </p>
                    </div>
                    <div className="flex items-start gap-2">
                      <i className="ri-check-double-line text-green-600 w-4 h-4 flex items-center justify-center mt-0.5"></i>
                      <p className="text-xs text-gray-600">
                        実物写真で状態を事前確認可能
                      </p>
                    </div>
                    <div className="flex items-start gap-2">
                      <i className="ri-check-double-line text-green-600 w-4 h-4 flex items-center justify-center mt-0.5"></i>
                      <p className="text-xs text-gray-600">
                        専門スタッフによる検品済み商品
                      </p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </main>

      {/* フッター */}
      <GlobalFooter />
    </div>
  );
}
